import{z as B,x as i,o as E,c as A,q as t,j as o,D as e,d as n,s as l,S as s}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"预防与避免","description":"","frontmatter":{"title":"预防与避免","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/deadlock-prevent.md","filePath":"cs/deadlock-prevent.md","lastUpdated":1791413859000}'),d={name:"cs/deadlock-prevent.md"};function p(c,a,_,h,m,C){const r=i("Mermaid");return E(),A("div",null,[a[2]||(a[2]=t('<h1 id="预防与避免" tabindex="-1">预防与避免 <a class="header-anchor" href="#预防与避免" aria-label="Permalink to &quot;预防与避免&quot;">​</a></h1><div class="epigraph"><p>预防在设计时拆掉 Coffman 四条件之一；避免在运行时拒绝走进不安全状态——银行家是后者，锁排序是前者。</p><footer>—— 据 Coffman, Elphick and Shoshani, 1971；Silberschatz et al. 对死锁处理策略的整理</footer></div><p><a href="/cs/deadlock-coffman">上一课</a>给出互斥、占有并等待、不可抢占、循环等待。缺口是把对策分成两档：<strong>预防</strong>（静态拆掉一条，使环不可能）与<strong>避免</strong>（动态，每次分配检查安全序列）。检测并恢复是第三档，本课点名，银行家算法细节下一课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>四条同时才可能死锁。预防：允许抢占资源（锁很难真抢）、禁止占有并等待（一次申请全部、或拿不到就放光已持有的）、或破坏循环等待（全系统锁序）。避免：进程先报最大需求，系统只进入仍存在安全序列的状态。缺口不是再举 AB-BA 例子，而是<strong>何时用静态纪律、何时用运行时检查</strong>。</p><p><span class="marginnote">术语翻译：「安全序列」就是一条排队还债的顺序——按它依次喂饱每个进程的最大需求、等它们跑完归还，中间任何一步都不会卡死。找得到这样一条顺序就叫安全态；一条都找不到才是不安全态。</span></p><p><span class="marginnote">检测：允许进可能死锁的状态，用资源分配图找环，再杀进程或抢资源。Unix 用户锁多半既不避免也不检测，靠预防式排序。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>选一条破：内核文档里的锁层级（稍后 lock-ordering 课展开）破循环等待；申请文件锁时非阻塞失败则回滚，破占有并等待。避免留给种类少、配额已知的资源。本课不把矩阵算法写完。</p><p><span class="marginnote">数字实例：系统共 10 份资源，已借出 7，剩 3；P1 声明最多再要 2，P2 最多再要 4。先把 3 份里的 2 份给 P1，P1 完成归还全部持有量，剩余变多再养 P2——存在安全序列，放行。若只剩 1 份，谁都喂不饱，任何新申请都只能挂起。</span></p>',10)),(E(),o(s,null,{default:e(()=>[l(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20FOUR%5B%22%E5%9B%9B%E6%9D%A1%E4%BB%B6%22%5D%20--%3E%20PREV%5B%22%E9%A2%84%E9%98%B2%3A%20%E6%B0%B8%E4%B9%85%E6%8B%86%E6%8E%89%E4%B8%80%E6%9D%A1%22%5D%0A%20%20FOUR%20--%3E%20AV%5B%22%E9%81%BF%E5%85%8D%3A%20%E5%8F%AA%E5%81%9C%E7%95%99%E5%9C%A8%E5%AE%89%E5%85%A8%E6%80%81%22%5D%0A%20%20FOUR%20--%3E%20DET%5B%22%E6%A3%80%E6%B5%8B%3A%20%E6%89%BE%E7%8E%AF%E5%86%8D%E6%81%A2%E5%A4%8D%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>与<a href="/cs/priority-inversion">优先级反转</a>：反转无环也可发生，不是本课对象。活锁也不是环。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>预防把正确性放到编码规范：违反锁序即可能死锁，锁依赖检测器抓动态违反。避免更灵活但要配额，通用 <code>malloc</code> 几乎给不出诚实的最大需求——所以<a href="/cs/banker-algorithm">银行家</a> 是教材算法，不是 Linux 页框分配器。检测有滞后与误杀。三档都比「假装不会死锁」贵，贵在不同地方。</p><p><span class="marginnote">常见误区：初学者容易以为「不安全态 = 已经死锁」。不安全只是「没有保证」：进程若提前释放，系统照样能走活；死锁才是环真的闭合。银行家策略保守地把系统挡在所有不安全态之外——宁可错拒，也不冒进。</span></p>',4)),(E(),o(s,null,{default:e(()=>[l(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E5%89%A9%E4%BD%99%203%20%E4%BB%BD%EF%BC%8CP1%20%E6%9C%80%E5%A4%9A%E5%B7%AE%202%EF%BC%8CP2%20%E6%9C%80%E5%A4%9A%E5%B7%AE%204%22%5D%20--%3E%20G1%5B%22%E7%BB%99%20P1%20%E4%B8%A4%E4%BB%BD%EF%BC%8CP1%20%E5%AE%8C%E6%88%90%E5%85%A8%E6%95%B0%E5%BD%92%E8%BF%98%22%5D%0A%20%20G1%20--%3E%20OK%5B%22%E4%BB%8D%E6%8E%92%E5%BE%97%E5%87%BA%E8%BF%98%E5%80%BA%E9%A1%BA%E5%BA%8F%EF%BC%9A%E5%AE%89%E5%85%A8%E6%80%81%EF%BC%8C%E6%94%BE%E8%A1%8C%22%5D%0A%20%20S%20--%3E%20G2%5B%22%E8%8B%A5%E6%8A%8A%E8%B5%84%E6%BA%90%E6%8C%A5%E9%9C%8D%E7%BB%99%E5%A4%A7%E7%94%B3%E8%AF%B7%E8%80%85%EF%BC%8C%E5%89%A9%200%22%5D%0A%20%20G2%20--%3E%20BAD%5B%22%E6%97%A0%E4%BA%BA%E8%83%BD%E6%BB%A1%E8%B6%B3%EF%BC%9A%E4%B8%8D%E5%AE%89%E5%85%A8%E6%80%81%EF%BC%8C%E6%8B%92%E7%BB%9D%E5%88%86%E9%85%8D%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把分布式死锁探针写完。可消耗资源（信号量 V）与可重用锁的图论不同，主干仍以可重用锁为准。银行家的安全序列下一课专写。</p><p>后课默认：预防靠破条件，避免靠安全态。安全序列如何检查，下一课银行家算法。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>预防：设计时去掉四条件之一；避免：运行时不进不安全态。</li><li>检测是第三档；通用 OS 对用户内存很少跑银行家。</li><li>安全序列算法是下一课。</li><li>出处：Coffman et al., 1971；Silberschatz et al., <em>OSC</em>。</li></ul>',5))])}const u=B(d,[["render",p]]);export{D as __pageData,u as default};
